CREATE TABLE meme_settlements(round_id TEXT PRIMARY KEY REFERENCES meme_rounds(id),cutoff INTEGER NOT NULL,input_hash TEXT NOT NULL,result_hash TEXT NOT NULL,context TEXT NOT NULL,voter_count INTEGER NOT NULL,allocation_count INTEGER NOT NULL,entitlement_count INTEGER NOT NULL,state TEXT NOT NULL CHECK(state IN('freezing','allocating','finalized')),mode TEXT NOT NULL CHECK(mode IN('observed','simulated')),created_at INTEGER NOT NULL,finalized_at INTEGER);
CREATE TABLE meme_settlement_inputs(round_id TEXT NOT NULL REFERENCES meme_settlements(round_id),fid INTEGER NOT NULL,rank INTEGER NOT NULL,payload TEXT NOT NULL,payload_hash TEXT NOT NULL,PRIMARY KEY(round_id,fid),UNIQUE(round_id,rank));
CREATE TABLE meme_allocations(id TEXT PRIMARY KEY,campaign_id TEXT NOT NULL REFERENCES meme_campaigns(id),release_index INTEGER NOT NULL CHECK(release_index BETWEEN 1 AND 10),release_at INTEGER NOT NULL,round_id TEXT REFERENCES meme_settlements(round_id),total TEXT NOT NULL,allocated TEXT NOT NULL,reserve TEXT NOT NULL,input_hash TEXT NOT NULL,result_hash TEXT NOT NULL,mode TEXT NOT NULL,reason TEXT,UNIQUE(campaign_id,release_index));
CREATE TABLE meme_entitlements(allocation_id TEXT NOT NULL REFERENCES meme_allocations(id),fid INTEGER NOT NULL,rank INTEGER NOT NULL,reward_wallet TEXT NOT NULL,amount TEXT NOT NULL,state TEXT NOT NULL CHECK(state='finalized_unfunded'),PRIMARY KEY(allocation_id,fid));
CREATE INDEX meme_entitlements_fid ON meme_entitlements(fid);
CREATE UNIQUE INDEX meme_one_launch_per_day ON meme_campaigns(date(launched_at/1000,'unixepoch'));
CREATE TRIGGER meme_checkpoint_no_rewind BEFORE UPDATE ON meme_ledger_checkpoints WHEN NEW.through_at<OLD.through_at OR NEW.through_slot<OLD.through_slot BEGIN SELECT RAISE(ABORT,'Source checkpoint cannot move backwards'); END;
CREATE TRIGGER meme_ledger_sealed_prefix BEFORE INSERT ON meme_ledger_events WHEN EXISTS(SELECT 1 FROM meme_ledger_seals s,json_each(s.scope_wallets) w WHERE s.campaign_id=NEW.campaign_id AND s.through_at>=NEW.event_at AND w.value IN(json_extract(NEW.payload,'$.wallet'),json_extract(NEW.payload,'$.from'),json_extract(NEW.payload,'$.to'))) BEGIN SELECT RAISE(ABORT,'Late event contradicts a completed source checkpoint'); END;
CREATE TRIGGER meme_inputs_immutable BEFORE UPDATE ON meme_settlement_inputs BEGIN SELECT RAISE(ABORT,'Settlement inputs are immutable'); END;
CREATE TRIGGER meme_inputs_no_delete BEFORE DELETE ON meme_settlement_inputs BEGIN SELECT RAISE(ABORT,'Settlement inputs are immutable'); END;
CREATE TRIGGER meme_allocations_immutable BEFORE UPDATE ON meme_allocations BEGIN SELECT RAISE(ABORT,'Allocations are immutable'); END;
CREATE TRIGGER meme_allocations_no_delete BEFORE DELETE ON meme_allocations BEGIN SELECT RAISE(ABORT,'Allocations are immutable'); END;
CREATE TRIGGER meme_entitlements_immutable BEFORE UPDATE ON meme_entitlements BEGIN SELECT RAISE(ABORT,'Entitlements are immutable'); END;
CREATE TRIGGER meme_entitlements_no_delete BEFORE DELETE ON meme_entitlements BEGIN SELECT RAISE(ABORT,'Entitlements are immutable'); END;
CREATE TRIGGER meme_settlement_no_delete BEFORE DELETE ON meme_settlements BEGIN SELECT RAISE(ABORT,'Settlement manifests are immutable'); END;
CREATE TRIGGER meme_settlement_manifest_immutable BEFORE UPDATE ON meme_settlements WHEN NEW.input_hash!=OLD.input_hash OR NEW.result_hash!=OLD.result_hash OR NEW.context!=OLD.context OR NEW.cutoff!=OLD.cutoff OR NEW.mode!=OLD.mode OR NEW.voter_count!=OLD.voter_count OR NEW.allocation_count!=OLD.allocation_count OR NEW.entitlement_count!=OLD.entitlement_count OR OLD.state='finalized' BEGIN SELECT RAISE(ABORT,'Settlement manifests are immutable'); END;
-- A newly backdated campaign would change every unsettled holding denominator.
CREATE TRIGGER meme_campaign_after_settlement BEFORE INSERT ON meme_campaigns WHEN EXISTS(SELECT 1 FROM meme_settlements WHERE cutoff>=NEW.launched_at AND cutoff<=NEW.ends_at) BEGIN SELECT RAISE(ABORT,'Register launches before settling their round'); END;
CREATE TRIGGER meme_settled_vote_insert BEFORE INSERT ON meme_votes WHEN EXISTS(SELECT 1 FROM meme_settlements WHERE round_id=NEW.round_id) BEGIN SELECT RAISE(ABORT,'Settlement votes are immutable'); END;
CREATE TRIGGER meme_settled_vote_update BEFORE UPDATE ON meme_votes WHEN EXISTS(SELECT 1 FROM meme_settlements WHERE round_id=OLD.round_id) BEGIN SELECT RAISE(ABORT,'Settlement votes are immutable'); END;
CREATE TRIGGER meme_settled_vote_delete BEFORE DELETE ON meme_votes WHEN EXISTS(SELECT 1 FROM meme_settlements WHERE round_id=OLD.round_id) BEGIN SELECT RAISE(ABORT,'Settlement votes are immutable'); END;
